package com.edunexa.app
import android.content.Intent
import android.os.Bundle
import android.view.View
import android.widget.*
import com.edunexa.app.data.UserProfile
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore
class ProfileSetupActivity:EduActivity(){
 override fun onCreate(state:Bundle?){super.onCreate(state);val user=FirebaseAuth.getInstance().currentUser?:run{Session.logout(this);return};val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(28,24,28,28)};setContentView(ScrollView(this).apply{addView(root)});root.addView(TextView(this).apply{text="Complete Your Account";textSize=26f});val role=Spinner(this).apply{adapter=ArrayAdapter(this@ProfileSetupActivity,android.R.layout.simple_spinner_dropdown_item,listOf("student","teacher","school"))};root.addView(role);val name=EditText(this).apply{hint="Full name / school name";setText(user.displayName.orEmpty())};val cls=EditText(this).apply{hint="Class / subject"};val phone=EditText(this).apply{hint="School phone number";inputType=android.text.InputType.TYPE_CLASS_PHONE};val address=EditText(this).apply{hint="School address"};listOf(name,cls,phone,address).forEach{root.addView(it)};val status=TextView(this);root.addView(status);root.addView(Button(this).apply{text="Save Profile";setOnClickListener{val selected=role.selectedItem.toString();val school=selected=="school";if(name.text.isBlank()||school&&(phone.text.isBlank()||address.text.isBlank())){status.text="Complete the required fields";return@setOnClickListener};isEnabled=false;val ref=FirebaseFirestore.getInstance().collection("users").document(user.uid);FirebaseFirestore.getInstance().runTransaction{t->if(!t.get(ref).exists())t.set(ref,UserProfile(uid=user.uid,name=name.text.toString().trim(),email=user.email.orEmpty(),role=selected,schoolName=if(school)name.text.toString().trim() else "",className=if(school)"" else cls.text.toString().trim(),contactNumber=if(school)phone.text.toString().trim() else "",address=if(school)address.text.toString().trim() else "",schoolApproved=!school))}.addOnSuccessListener{startActivity(Intent(this@ProfileSetupActivity,AuthActivity::class.java).apply{flags=Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK});finish()}.addOnFailureListener{isEnabled=true;status.text=it.message}}});root.addView(Button(this).apply{text="Sign Out";setOnClickListener{Session.logout(this@ProfileSetupActivity)}})}
}
